head.script:
// 상장관련공통함수
scwin.svrGubun = js_svrGubun; // DR전환시
scwin.gWorkDD;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        MxTab_1.setSelectedTabIndex(1);
        await scwin.setCode();

        // 오늘날짜로 초기화시킨다.
        const today = $c.ut.cGetToday("yyyymmdd");
        edt_BASE_DD.setValue(today);
        rdo_TERM.setValue(Number(Number(today.substring(4, 6)) % 6 - 1));
        if (rdo_TERM.getValue() < 1) {
            rdo_TERM.setValue('5');
        }
        $c.cm.fn_com_isur(txb_ISU_CD, txb_ISU_NM);
        Grd_com_isur.style.zIndex = 30;
        if (scwin.svrGubun === "dr") {
            await $c.win.alert("DR에서 운영될때는 [금일 장상태]가 제공되지 않습니다.");
            txb_TR_STATE_CD.setValue("-");
            txb_ATS_STATE_CD.setValue("-");
        } else {
            scwin.setTrstatcd();
        }

        // round처리
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35603.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        btn_Search.setDisabled(false);
        btn_Search.setBackgroundImage("../img/btn_select.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35603.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        // alert_error(dts_List);
        await $c.win.alert("해당 일자의 데이터가 존재하지 않습니다.");
        btn_Search.setDisabled(false);
        btn_Search.setBackgroundImage("../img/btn_select.gif");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35603.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List2_OnLoadCompleted
 * @description dts_List2 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List2_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        btn_Search.setDisabled(false);
        btn_Search.setBackgroundImage("../img/btn_select.gif");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35603.dts_List2_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List2_OnLoadError
 * @description dts_List2 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List2_OnLoadError = async function() {
    try {
        // alert_error(dts_List);
        await $c.win.alert("해당 일자의 데이터가 존재하지 않습니다.");
        btn_Search.setDisabled(false);
        btn_Search.setBackgroundImage("../img/btn_select.gif");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35603.dts_List2_OnLoadError" });
    }
};

/**
 * @method
 * @name img_BASE_DD_onclick
 * @description img_BASE_DD 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_BASE_DD_onclick = function() {
    try {
        popUpCalendar2(edt_BASE_DD);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35603.img_BASE_DD_onclick" });
    }
};

/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        let tIndex = MxTab_1.getSelectedTabIndex();
        // 엑셀 로그
        $c.stf.doLogSave("ULDSTF35603.xml", SCREN_PROCS_TP_CD_07);
        if (tIndex === 1) {
            $c.data.downloadGridViewExcel(grd_List, {fileName: "거래현황 -거래량요건 목록", type: "8"});
        } else if (tIndex === 2) {
            $c.data.downloadGridViewExcel(grd_List2, {fileName: "거래현황 -종류주식 거래량요건 목록", type: "8"});
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35603.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        let tIndex = MxTab_1.getSelectedTabIndex();
        if (tIndex === 1) {
            await scwin.listSync();
        } else if (tIndex === 2) {
            await scwin.listSync2();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35603.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35603.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_com_isur_OnFilter
 * @description Mx Data Set com isur On Filter 처리
 * @param {Number} row 행 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.MxDataSet_com_isur_OnFilter = function(row) {
    try {
        if (skw !== "" && foColum === "1") {
            f1 = MxDataSet_com_isur.getCellData(row, "COM_ABBRV");
            f2 = MxDataSet_com_isur.getCellData(row, "OLD_COM_ABBRV");
            if (f1.indexOf(skw) !== -1 || f2.indexOf(skw) !== -1) return true;

            else return false;
        } else return true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35603.MxDataSet_com_isur_OnFilter" });
    }
};

/**
 * @method
 * @name txb_ISU_CD_onkeyup
 * @description txb_ISU_CD 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISU_CD_onkeyup = function() {
    try {
        if (txb_ISU_CD.getValue() === "") {
            Grd_com_isur.style.display = "none";
        } else {
            if (window.event.keyCode === 40) {
                // 아래화살표눌렀을때 그리드로 포커스
                Grd_com_isur.focus();
            } else {
                $c.cm.fn_com_isur_nm(window.event.keyCode);
            }
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35603.txb_ISU_CD_onkeyup" });
    }
};

/**
 * @method
 * @name txb_ISU_CD_onfocus
 * @description txb_ISU_CD 포커스 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISU_CD_onfocus = function() {
    try {
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35603.txb_ISU_CD_onfocus" });
    }
};

/**
 * @method
 * @name txb_ISU_CD_onblur
 * @description txb_ISU_CD 포커스 이탈 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_ISU_CD_onblur = function() {
    try {
        if (stFocusGrid === false) {
            Grd_com_isur.style.display = "none";
        }
        if (txb_ISU_CD.getValue() === "") {
            txb_ISU_NM.setValue("");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35603.txb_ISU_CD_onblur" });
    }
};

/**
 * @method
 * @name img_ISU_NM_onclick
 * @description img_ISU_NM 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_ISU_NM_onclick = function() {
    try {
        $c.stockSearch.JongmokSearch(txb_ISU_CD, txb_ISU_NM, SECUGRP_ID_ST, js_market, "A");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35603.img_ISU_NM_onclick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKeyPress
 * @description Grd com isur On Key Press 처리
 * @param {*} kcode kcode
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKeyPress = function(kcode) {
    try {
        if (kcode === '13') {
            $c.cm.fn_com_Confirm_set();
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35603.Grd_com_isur_OnKeyPress" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnDblClick
 * @description Grd_com_isur 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnDblClick = function(row, colid) {
    try {
        $c.cm.fn_com_Confirm_set();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35603.Grd_com_isur_OnDblClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnClick
 * @description Grd_com_isur 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnClick = function(row, colid) {
    try {
        Grd_com_isur.style.display = "";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35603.Grd_com_isur_OnClick" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnSetFocus
 * @description Grd com isur On Set Focus 처리
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnSetFocus = function() {
    try {
        stFocusGrid = true;
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35603.Grd_com_isur_OnSetFocus" });
    }
};

/**
 * @method
 * @name Grd_com_isur_OnKillFocus
 * @description Grd_com_isur 포커스 이탈 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {void}
 * @hidden N
 */
scwin.Grd_com_isur_OnKillFocus = function() {
    try {
        stFocusGrid = false;
        Grd_com_isur.style.display = "none";
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF35603.Grd_com_isur_OnKillFocus" });
    }
};

/**
 * @method
 * @name MxTab_1_OnSelChanged
 * @description Mx Tab 1 On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.MxTab_1_OnSelChanged = async function(nIndex) {
    try {
        let eCnt = 0; // 각 dataset 별 표시 count
        let tIndex = MxTab_1.getSelectedTabIndex();
        // alert(tIndex);
        if (tIndex === 1) {
            eCnt = dts_List.getRowCount();
        } else if (tIndex === 2) {
            eCnt = dts_List2.getRowCount();
        }
        $c.stf.fillGridHeaderTotalCnt(eCnt, panel_page);

        // tab을 선택 시 기존 그리드의 '조회결과 없음'표시를 닫는다.
        if ($c.frame.path("NoData") !== null) {
            await $c.win.closePopup();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35603.MxTab_1_OnSelChanged" });
    }
};

/**
 * @method
 * @name dts_TR_STATE_CD_OnLoadError
 * @description dts_TR_STATE_CD 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_TR_STATE_CD_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_TR_STATE_CD);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35603.dts_TR_STATE_CD_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_WorkDD_OnLoadError
 * @description dts_WorkDD 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_WorkDD_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_WorkDD);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF35603.dts_WorkDD_OnLoadError" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setCode = async function() {
    const sbmOptions = {
        id : "sbm_dts_IndCd",
        action : "/AdminAndDlstedDetection.do",
        ref : "",
        target : "dts_IndCd=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name workDD
 * @description work DD 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.workDD = async function() {
    const sbmOptions = {
        id : "sbm_dts_WorkDD",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_WorkDD=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    scwin.gWorkDD = dts_WorkDD.getCellData(1, "CALND_DD");
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name listSync
 * @description 거래량 요건  검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    if (edt_BASE_DD.getValue() > $c.ut.cGetToday("yyyymmdd")) {
        await $c.win.alert("현재일자보다 기준일자가 이후일 수 없습니다.");
        edt_BASE_DD.focus();
        return;
    }
    if (rdo_TERM.getValue() < 1) {
        await $c.win.alert("기준월을 선택하세요.");
        rdo_TERM.focus();
        return;
    }
    btn_Search.setDisabled(true);
    btn_Search.setBackgroundImage("../img/btn_select_d.gif");
    if (scwin.svrGubun === "dr") {
        // DR일 경우 2011.01.28
        await $c.win.alert("DR에서 운영될때는 [금일 장상태]가 제공되지 않습니다.");
        txb_TR_STATE_CD.setValue("-");
        txb_ATS_STATE_CD.setValue("-");
    } else {
        scwin.setTrstatcd();
    }
    // var url = "/AdminAndDlstedDetection.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01+"&method=getTransList&For=TTA&inputMessageId=AADD_IN&outputMessageId=AADD_OUT_TTA";
    // url+= "&ISUR_CD=" + getObjectValue(txb_ISU_CD);
    // url+= "&BASE_DT=" + getObjectValue(edt_BASE_DD);
    // url+= "&IND_CD=" + getObjectValue(cmb_IND_DD);
    // url+= "&TERM=" + getObjectValue(rdo_TERM);
    await scwin.workDD();
    let IND_CD = cmb_IND_DD.getValue();
    let ISU_CD = txb_ISU_CD.getValue();
    let BASE_DD = edt_BASE_DD.getValue();
    let TERM = "-" + rdo_TERM.getValue();
    if (ISU_CD === "") ISU_CD = "%";
    url = "/listingCommon.do?SCREN_ID=" + "ULDSTF35603.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=AADD_OUT_TTA" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.detection.trans_transamt.list" + "&{P}param01=" + BASE_DD + // 기준일
        "&{P}param02=" + scwin.gWorkDD + "&{P}param03=" + scwin.gWorkDD + "&{P}param04=" + scwin.gWorkDD + "&{P}param05=" + IND_CD + "&{P}param06=" + IND_CD + "&{P}param07=" + ISU_CD + "&{P}param08=" + scwin.gWorkDD + "&{P}param09=" + TERM + "&{P}param10=" + scwin.gWorkDD + "&{P}param11=" + BASE_DD + // 기준일
        "&{P}param12=" + TERM + "&{P}param13=" + BASE_DD + // 기준일
        "&{P}param14=" + BASE_DD + // 기준일
        "&{P}param15=" + TERM + "&{P}param16=" + BASE_DD + // 기준일
        "&{P}param17=" + BASE_DD + // 기준일
        "&{P}param18=" + TERM + "&{P}param19=" + BASE_DD; // 기준일

    dts_List.DataID = encodeURI(url);
    dts_List.reset();

};

/**
 * @method
 * @name listSync2
 * @description 종류주식 거래량 요건  검색
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync2 = async function() {
    if (edt_BASE_DD.getValue() > $c.ut.cGetToday("yyyymmdd")) {
        await $c.win.alert("현재일자보다 기준일자가 이후일 수 없습니다.");
        edt_BASE_DD.focus();
        return;
    }
    if (rdo_TERM.getValue() < 1) {
        await $c.win.alert("기준월을 선택하세요.");
        rdo_TERM.focus();
        return;
    }
    btn_Search.setDisabled(true);
    btn_Search.setBackgroundImage("../img/btn_select_d.gif");
    if (scwin.svrGubun === "dr") {
        // DR일 경우 2011.01.28
        await $c.win.alert("DR에서 운영될때는 [금일 장상태]가 제공되지 않습니다.");
        txb_TR_STATE_CD.setValue("-");
        txb_ATS_STATE_CD.setValue("-");
    } else {
        scwin.setTrstatcd();
    }
    /*
    var url = "/AdminAndDlstedDetection.do?SCREN_ID="+vScrenID+"&SCREN_PROCES_TP_CD="+SCREN_PROCS_TP_CD_01
              +"&method=getTransList&For=KNTTA&inputMessageId=AADD_IN&outputMessageId=AADD_OUT_TTA";
    url+= "&ISUR_CD=" + getObjectValue(txb_ISU_CD);
    url+= "&BASE_DT=" + getObjectValue(edt_BASE_DD);
    url+= "&IND_CD=" + getObjectValue(cmb_IND_DD);
    url+= "&TERM=" + getObjectValue(rdo_TERM);
     */
    await scwin.workDD();
    let IND_CD = cmb_IND_DD.getValue();
    let ISU_CD = txb_ISU_CD.getValue();
    let BASE_DD = edt_BASE_DD.getValue();
    let TERM = "-" + rdo_TERM.getValue();
    if (ISU_CD === "") ISU_CD = "%";
    url = "/listingCommon.do?SCREN_ID=" + "ULDSTF35603.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneral" + "&outputMessageId=AADD_OUT_TTA" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=krx.lds.stf.lstmgt.detection.trans_kntransamt.list" + "&{P}param01=" + BASE_DD + // 기준일
        "&{P}param02=" + scwin.gWorkDD + "&{P}param03=" + scwin.gWorkDD + "&{P}param04=" + scwin.gWorkDD + "&{P}param05=" + IND_CD + "&{P}param06=" + IND_CD + "&{P}param07=" + ISU_CD + "&{P}param08=" + scwin.gWorkDD + "&{P}param09=" + TERM + "&{P}param10=" + scwin.gWorkDD + "&{P}param11=" + BASE_DD + // 기준일
        "&{P}param12=" + TERM + "&{P}param13=" + BASE_DD + // 기준일
        "&{P}param14=" + BASE_DD + // 기준일
        "&{P}param15=" + TERM + "&{P}param16=" + BASE_DD + // 기준일
        "&{P}param17=" + BASE_DD + // 기준일
        "&{P}param18=" + TERM + "&{P}param19=" + BASE_DD; // 기준일

    dts_List2.DataID = encodeURI(url);
    dts_List2.reset();

};

